@Service
public class DomainUserDetailsService implements UserDetailsService {

    private final UserRepository userRepository;

    public DomainUserDetailsService(UserRepository userRepository) {
        this.userRepository = userRepository;
    }

    @Override
    @Transactional(readOnly = true)
    public UserDetails loadUserByUsername(String username) throws UsernameNotFoundException {
        com.example.domain.User domainUser = userRepository.findByEmail(username)
            .orElseThrow(() -> new UsernameNotFoundException("User not found with email: " + username));

        Set<GrantedAuthority> authorities = domainUser.getRoles().stream(
            ).map(role -> new SimpleGrantedAuthority(role.getName()))
            .collect(Collectors.toSet());

        return new org.springframework.security.core.userdetails.User(
            domainUser.getEmail(),
            domainUser.getPasswordHash(),
            domainUser.isEnabled(),
            domainUser.isAccountNonExpired(),
            domainUser.isCredentialsNonExpired(),
            domainUser.isAccountNonLocked(),
            authorities
        );
    }
}
